"BQ-a-T4-b2-3":"<svg viewBox=\"-95 -14 560 193\" role=\"img\" aria-label=\"Fonte de corrente de 30 ampères alimentando 10 e 5 ohms em paralelo: 10 ampères no de 10 ohms e 20 no de 5 ohms\"><path class=\"s-wire s-ink\" d=\"M70 0 L70 37\"/><path class=\"s-wire s-ink\" d=\"M70 93 L70 130\"/><g transform=\"translate(70 65) rotate(90)\"><path class=\"s-wire s-ink\" d=\"M-28 0 H-15 M15 0 H28\"/><circle class=\"s-comp\" cx=\"0\" cy=\"0\" r=\"15\"/><path class=\"s-wire s-ink\" d=\"M-9 0 H9 M9 0 l-5 -4 M9 0 l-5 4\"/></g><text class=\"s-ts\" x=\"48\" y=\"69\" text-anchor=\"end\">30 A</text><circle class=\"s-f-ink\" cx=\"70\" cy=\"0\" r=\"3.6\"/><circle class=\"s-f-ink\" cx=\"70\" cy=\"130\" r=\"3.6\"/><path class=\"s-wire s-ink\" d=\"M70 0 L130 0\"/><circle class=\"s-f-ink\" cx=\"130\" cy=\"0\" r=\"3.6\"/><circle class=\"s-f-ink\" cx=\"130\" cy=\"130\" r=\"3.6\"/><path class=\"s-wire s-ink\" d=\"M130 0 L130 37\"/><g transform=\"translate(130 65) rotate(90)\"><path class=\"s-wire s-ink\" d=\"M-28 0 H-21 L-17 -8 L-9 8 L-1 -8 L7 8 L15 -8 L21 0 H28\"/></g><text class=\"s-ts\" x=\"152\" y=\"53\" text-anchor=\"start\">R₁ = 10 Ω</text><text class=\"s-fa\" x=\"152\" y=\"69\" text-anchor=\"start\">I = 10 A</text><text class=\"s-fb\" x=\"152\" y=\"85\" text-anchor=\"start\">U = 100 V</text><polygon class=\"s-f-pa\" points=\"130,28 135,16 125,16\"/><path class=\"s-wire s-ink\" d=\"M130 93 L130 130\"/><path class=\"s-wire s-ink\" d=\"M130 0 L233.7 0\"/><circle class=\"s-f-ink\" cx=\"233.7\" cy=\"0\" r=\"3.6\"/><circle class=\"s-f-ink\" cx=\"233.7\" cy=\"130\" r=\"3.6\"/><path class=\"s-wire s-ink\" d=\"M233.7 0 L233.7 37\"/><g transform=\"translate(233.7 65) rotate(90)\"><path class=\"s-wire s-ink\" d=\"M-28 0 H-21 L-17 -8 L-9 8 L-1 -8 L7 8 L15 -8 L21 0 H28\"/></g><text class=\"s-ts\" x=\"255.7\" y=\"53\" text-anchor=\"start\">R₂ = 5 Ω</text><text class=\"s-fa\" x=\"255.7\" y=\"69\" text-anchor=\"start\">I = 20 A</text><text class=\"s-fb\" x=\"255.7\" y=\"85\" text-anchor=\"start\">U = 100 V</text><polygon class=\"s-f-pa\" points=\"233.7,28 238.7,16 228.7,16\"/><path class=\"s-wire s-ink\" d=\"M233.7 93 L233.7 130\"/><path class=\"s-wire s-ink\" d=\"M70 130 L233.7 130\"/><text class=\"s-tm\" x=\"30\" y=\"164\" text-anchor=\"start\">divisor de corrente: I₁ = 30·5/(10+5) = 10 A</text></svg>",
