"BQ-e-A1-b4-0":"<svg viewBox=\"-42 -86 560 331\" role=\"img\" aria-label=\"Amplificador operacional inversor com 4 e 20 quilo-ohms: entrada de menos 0,6 volt e saída de mais 3 volts\"><path class=\"s-comp\" d=\"M260 46 L260 134 L340 90 Z\"/><text class=\"s-ts\" x=\"269\" y=\"75\" text-anchor=\"start\">−</text><text class=\"s-ts\" x=\"269\" y=\"119\" text-anchor=\"start\">+</text><path class=\"s-wire s-ink\" d=\"M340 90 L410 90\"/><circle class=\"s-comp\" cx=\"410\" cy=\"90\" r=\"4.5\"/><text class=\"s-fb\" x=\"422\" y=\"94\" text-anchor=\"start\">Vo = +3,0 V</text><circle class=\"s-f-ink\" cx=\"376\" cy=\"90\" r=\"3.6\"/><path class=\"s-wire s-ink\" d=\"M376 90 L376 -40 L260 -40\"/><g transform=\"translate(318 -40) rotate(0)\"><path class=\"s-wire s-ink\" d=\"M-28 0 H-21 L-17 -8 L-9 8 L-1 -8 L7 8 L15 -8 L21 0 H28\"/></g><text class=\"s-ts\" x=\"318\" y=\"-64\" text-anchor=\"middle\">Rf = 20 kΩ</text><path class=\"s-wire s-ink\" d=\"M260 -40 L224 -40 L224 68\"/><path class=\"s-wire s-ink\" d=\"M224 68 L260 68\"/><circle class=\"s-f-ink\" cx=\"224\" cy=\"68\" r=\"3.6\"/><path class=\"s-wire s-ink\" d=\"M60 68 L224 68\"/><g transform=\"translate(120 68) rotate(0)\"><path class=\"s-wire s-ink\" d=\"M-28 0 H-21 L-17 -8 L-9 8 L-1 -8 L7 8 L15 -8 L21 0 H28\"/></g><text class=\"s-ts\" x=\"120\" y=\"44\" text-anchor=\"middle\">Ri = 4 kΩ</text><path class=\"s-wire s-ink\" d=\"M60 68 L92 68\"/><circle class=\"s-comp\" cx=\"60\" cy=\"68\" r=\"4.5\"/><text class=\"s-fb\" x=\"54\" y=\"72\" text-anchor=\"end\">Vi = −0,6 V</text><path class=\"s-wire s-ink\" d=\"M260 112 L230 112 L230 126\"/><path class=\"s-wire s-ink\" d=\"M230 126 L230 136\"/><path class=\"s-wire s-ink\" d=\"M219 136 L241 136\"/><path class=\"s-wire s-ink\" d=\"M223 141 L237 141\"/><path class=\"s-wire s-ink\" d=\"M227 146 L233 146\"/><text class=\"s-tm\" x=\"20\" y=\"230\" text-anchor=\"start\">Vo = −(Rf/Ri)·Vi = −(20/4)·(−0,6) = +3,0 V</text></svg>",
