"BQ-e-A2-y2":"<svg viewBox=\"-168 -14 560 211\" role=\"img\" aria-label=\"Laço de 4 a 20 miliampères de transmissor de pressão com resistor de 250 ohms em entrada de 0 a 5 volts: leitura 2.048 corresponde a 2,5 volts, 10 miliampères e 3,75 bar\"><path class=\"s-wire s-ink\" d=\"M70 0 L70 37\"/><path class=\"s-wire s-ink\" d=\"M70 93 L70 130\"/><g transform=\"translate(70 65) rotate(90)\"><path class=\"s-wire s-ink\" d=\"M-28 0 H-15 M15 0 H28\"/><circle class=\"s-comp\" cx=\"0\" cy=\"0\" r=\"15\"/><path class=\"s-wire s-ink\" d=\"M-9 0 H9 M9 0 l-5 -4 M9 0 l-5 4\"/></g><text class=\"s-ts\" x=\"48\" y=\"61\" text-anchor=\"end\">transmissor = 10 mA</text><text class=\"s-tm\" x=\"48\" y=\"77\" text-anchor=\"end\">0–10 bar</text><circle class=\"s-f-ink\" cx=\"70\" cy=\"0\" r=\"3.6\"/><circle class=\"s-f-ink\" cx=\"70\" cy=\"130\" r=\"3.6\"/><path class=\"s-wire s-ink\" d=\"M70 0 L110 0\"/><path class=\"s-wire s-ink\" d=\"M110 0 L110 37\"/><path class=\"s-wire s-ink\" d=\"M110 93 L110 130\"/><g transform=\"translate(110 65) rotate(90)\"><path class=\"s-wire s-ink\" d=\"M-28 0 H-21 L-17 -8 L-9 8 L-1 -8 L7 8 L15 -8 L21 0 H28\"/></g><text class=\"s-ts\" x=\"132\" y=\"45\" text-anchor=\"start\">resistor = 250 Ω</text><text class=\"s-fb\" x=\"132\" y=\"61\" text-anchor=\"start\">U = 2,5 V</text><text class=\"s-tm\" x=\"132\" y=\"77\" text-anchor=\"start\">entrada A/D 0–5 V</text><text class=\"s-tm\" x=\"132\" y=\"93\" text-anchor=\"start\">leitura: 2.048</text><circle class=\"s-f-ink\" cx=\"110\" cy=\"0\" r=\"3.6\"/><circle class=\"s-f-ink\" cx=\"110\" cy=\"130\" r=\"3.6\"/><path class=\"s-wire s-ink\" d=\"M70 130 L110 130\"/><text class=\"s-tm\" x=\"30\" y=\"164\" text-anchor=\"start\">2.048/4.096·5 = 2,5 V → 2,5/250 = 10 mA</text><text class=\"s-tm\" x=\"30\" y=\"182\" text-anchor=\"start\">P = (10 − 4)/16·10 bar = 3,75 bar</text></svg>",
