"BQ-e-C1-b6-0":"<svg viewBox=\"-208 -14 560 193\" role=\"img\" aria-label=\"Carga resistiva monofásica de 3.810 watts entre fase e neutro em 127 volts: 30 ampères\"><path class=\"s-wire s-ink\" d=\"M70 0 L70 37\"/><path class=\"s-wire s-ink\" d=\"M70 93 L70 130\"/><g transform=\"translate(70 65) rotate(90)\"><path class=\"s-wire s-ink\" d=\"M-28 0 H-15 M15 0 H28\"/><circle class=\"s-comp\" cx=\"0\" cy=\"0\" r=\"15\"/><path class=\"s-wire s-ink\" d=\"M-9 0 q4.5 -9 9 0 t9 0\"/></g><text class=\"s-ts\" x=\"48\" y=\"61\" text-anchor=\"end\">fase–neutro = 127 V</text><text class=\"s-fa\" x=\"48\" y=\"77\" text-anchor=\"end\">I = 30 A</text><polygon class=\"s-f-pa\" points=\"70,14 65,26 75,26\"/><circle class=\"s-f-ink\" cx=\"70\" cy=\"0\" r=\"3.6\"/><circle class=\"s-f-ink\" cx=\"70\" cy=\"130\" r=\"3.6\"/><path class=\"s-wire s-ink\" d=\"M70 0 L110 0\"/><path class=\"s-wire s-ink\" d=\"M110 0 L110 37\"/><path class=\"s-wire s-ink\" d=\"M110 93 L110 130\"/><g transform=\"translate(110 65) rotate(90)\"><path class=\"s-wire s-ink\" d=\"M-28 0 H-21 L-17 -8 L-9 8 L-1 -8 L7 8 L15 -8 L21 0 H28\"/></g><text class=\"s-ts\" x=\"132\" y=\"61\" text-anchor=\"start\">carga = 4,23 Ω</text><text class=\"s-tm\" x=\"132\" y=\"77\" text-anchor=\"start\">P = 3.810 W</text><circle class=\"s-f-ink\" cx=\"110\" cy=\"0\" r=\"3.6\"/><circle class=\"s-f-ink\" cx=\"110\" cy=\"130\" r=\"3.6\"/><path class=\"s-wire s-ink\" d=\"M70 130 L110 130\"/><text class=\"s-tm\" x=\"30\" y=\"164\" text-anchor=\"start\">I = P/V = 3.810/127 = 30 A</text></svg>",
