"BQ-e-C1-x6":"<svg viewBox=\"-124 -14 560 193\" role=\"img\" aria-label=\"Carga monofásica de 4,4 quilowatts em 220 volts com fator de potência 0,8: 25 ampères\"><path class=\"s-wire s-ink\" d=\"M70 0 L70 37\"/><path class=\"s-wire s-ink\" d=\"M70 93 L70 130\"/><g transform=\"translate(70 65) rotate(90)\"><path class=\"s-wire s-ink\" d=\"M-28 0 H-15 M15 0 H28\"/><circle class=\"s-comp\" cx=\"0\" cy=\"0\" r=\"15\"/><path class=\"s-wire s-ink\" d=\"M-9 0 q4.5 -9 9 0 t9 0\"/></g><text class=\"s-ts\" x=\"48\" y=\"61\" text-anchor=\"end\">220 V</text><text class=\"s-fa\" x=\"48\" y=\"77\" text-anchor=\"end\">I = 25 A</text><polygon class=\"s-f-pa\" points=\"70,14 65,26 75,26\"/><circle class=\"s-f-ink\" cx=\"70\" cy=\"0\" r=\"3.6\"/><circle class=\"s-f-ink\" cx=\"70\" cy=\"130\" r=\"3.6\"/><path class=\"s-wire s-ink\" d=\"M70 0 L110 0\"/><path class=\"s-wire s-ink\" d=\"M110 0 L110 37\"/><path class=\"s-wire s-ink\" d=\"M110 93 L110 130\"/><g transform=\"translate(110 65) rotate(90)\"><path class=\"s-wire s-ink\" d=\"M-28 0 H-20 M20 0 H28\"/><rect class=\"s-comp\" x=\"-20\" y=\"-9\" width=\"40\" height=\"18\"/></g><text class=\"s-ts\" x=\"132\" y=\"61\" text-anchor=\"start\">carga = 4,4 kW</text><text class=\"s-tm\" x=\"132\" y=\"77\" text-anchor=\"start\">FP = 0,8 ind.</text><circle class=\"s-f-ink\" cx=\"110\" cy=\"0\" r=\"3.6\"/><circle class=\"s-f-ink\" cx=\"110\" cy=\"130\" r=\"3.6\"/><path class=\"s-wire s-ink\" d=\"M70 130 L110 130\"/><text class=\"s-tm\" x=\"30\" y=\"164\" text-anchor=\"start\">I = P/(V·cos φ) = 4.400/(220·0,8) = 25 A</text></svg>",
