"BQ-e-I3-b1-2":"<svg viewBox=\"-95 -14 560 193\" role=\"img\" aria-label=\"Galvanômetro de 5 miliampères e 40 ohms com shunt em paralelo de 4,44 ohms para medir até 50 miliampères\"><path class=\"s-wire s-ink\" d=\"M70 0 L70 37\"/><path class=\"s-wire s-ink\" d=\"M70 93 L70 130\"/><g transform=\"translate(70 65) rotate(90)\"><path class=\"s-wire s-ink\" d=\"M-28 0 H-15 M15 0 H28\"/><circle class=\"s-comp\" cx=\"0\" cy=\"0\" r=\"15\"/><path class=\"s-wire s-ink\" d=\"M-9 0 H9 M9 0 l-5 -4 M9 0 l-5 4\"/></g><text class=\"s-ts\" x=\"48\" y=\"61\" text-anchor=\"end\">50 mA</text><text class=\"s-tm\" x=\"48\" y=\"77\" text-anchor=\"end\">fundo de escala</text><circle class=\"s-f-ink\" cx=\"70\" cy=\"0\" r=\"3.6\"/><circle class=\"s-f-ink\" cx=\"70\" cy=\"130\" r=\"3.6\"/><path class=\"s-wire s-ink\" d=\"M70 0 L130 0\"/><circle class=\"s-f-ink\" cx=\"130\" cy=\"0\" r=\"3.6\"/><circle class=\"s-f-ink\" cx=\"130\" cy=\"130\" r=\"3.6\"/><path class=\"s-wire s-ink\" d=\"M130 0 L130 37\"/><g transform=\"translate(130 65) rotate(90)\"><path class=\"s-wire s-ink\" d=\"M-28 0 H-20 M20 0 H28\"/><rect class=\"s-comp\" x=\"-20\" y=\"-9\" width=\"40\" height=\"18\"/></g><text class=\"s-ts\" x=\"152\" y=\"53\" text-anchor=\"start\">galvanômetro = 40 Ω</text><text class=\"s-fa\" x=\"152\" y=\"69\" text-anchor=\"start\">I = 5 mA</text><text class=\"s-fb\" x=\"152\" y=\"85\" text-anchor=\"start\">U = 0,2 V</text><polygon class=\"s-f-pa\" points=\"130,28 135,16 125,16\"/><path class=\"s-wire s-ink\" d=\"M130 93 L130 130\"/><path class=\"s-wire s-ink\" d=\"M130 0 L306.7 0\"/><circle class=\"s-f-ink\" cx=\"306.7\" cy=\"0\" r=\"3.6\"/><circle class=\"s-f-ink\" cx=\"306.7\" cy=\"130\" r=\"3.6\"/><path class=\"s-wire s-ink\" d=\"M306.7 0 L306.7 37\"/><g transform=\"translate(306.7 65) rotate(90)\"><path class=\"s-wire s-ink\" d=\"M-28 0 H-21 L-17 -8 L-9 8 L-1 -8 L7 8 L15 -8 L21 0 H28\"/></g><text class=\"s-ts\" x=\"328.7\" y=\"53\" text-anchor=\"start\">shunt = 4,44 Ω</text><text class=\"s-fa\" x=\"328.7\" y=\"69\" text-anchor=\"start\">I = 45 mA</text><text class=\"s-fb\" x=\"328.7\" y=\"85\" text-anchor=\"start\">U = 0,2 V</text><polygon class=\"s-f-pa\" points=\"306.7,28 311.7,16 301.7,16\"/><path class=\"s-wire s-ink\" d=\"M306.7 93 L306.7 130\"/><path class=\"s-wire s-ink\" d=\"M70 130 L306.7 130\"/><text class=\"s-tm\" x=\"30\" y=\"164\" text-anchor=\"start\">Rsh = 0,2 V / 45 mA ≈ 4,44 Ω (a mesma tensão nos dois)</text></svg>",
